Fixpoint cellsZ (m : word -> option byte) (l : list (Z * word)) : Prop :=
  match l with
  | [] => True
  | (a, v) :: t => rdn SEGS m (Z_to_bv 64 a) 8 = Some (word_to_le_bytes 8 v) /\ cellsZ m t
  end.

